        return self.g.bbox_cells(pts[:, 0].min() - margin_mm, pts[:, 1].min() - margin_mm,
                                 pts[:, 0].max() + margin_mm, pts[:, 1].max() + margin_mm)

    def masks(self, code, win, soft=False):
        r0, r1, c0, c1 = win
        res = self.res
        w2 = self.width[code] / 2
        Rt = (w2 + self.C) / res + 0.8
        Rv = (self.via_d / 2 + self.C) / res + 0.8
        Re = (w2 + self.rules["edge"]) / res + 0.8
        Rve = (self.via_d / 2 + self.rules["edge"]) / res + 0.8
        Rh = (self.via_drill / 2 + self.rules["h2h"]) / res + 0.8
        NL = len(self.layers)
        edge = self.edge[r0:r1, c0:c1]
        blk = np.zeros((NL, r1 - r0, c1 - c0), bool)
        sblk = np.zeros_like(blk)
        vblk = dilate(edge, Rve) | dilate(self.holes[r0:r1, c0:c1], Rh) | self.keep_via[r0:r1, c0:c1]
        soft_m = np.zeros_like(blk) if soft else None
        ed = dilate(edge, Re)
        ed2 = dilate(edge, Re + 0.75)
        for li in range(NL):
            po = self.pad_own[li, r0:r1, c0:c1]
            to = self.trk_own[li, r0:r1, c0:c1]
            pother = (po != 0) & (po != code)
            tother = (to != 0) & (to != code)
